<?php
require_once __DIR__.'/conexion.php';
require_once __DIR__.'/reporte_utilidad.php';
require_once __DIR__.'/reporte_movimientos.php';
final class dashboard
{
    public function __construct(private ?PDO $db=null){$this->db??=(new conexion())->con();}
    private function q(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private function fecha(string $valor):string{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$valor);if(!$d||$d->format('Y-m-d')!==$valor)throw new InvalidArgumentException('Selecciona fechas válidas.');return $valor;}
    public function resumen(int $loc,string $inicio,string $fin):array{
        $inicio=$this->fecha($inicio);$fin=$this->fecha($fin);if($inicio>$fin)throw new InvalidArgumentException('La fecha inicial no puede superar la final.');
        $desde=new DateTimeImmutable($inicio);$hasta=new DateTimeImmutable($fin);if($desde->diff($hasta)->days>366)throw new InvalidArgumentException('Selecciona como máximo un año.');$finExclusivo=$hasta->modify('+1 day')->format('Y-m-d');
        $ventas=$this->q('SELECT COUNT(*) operaciones,COALESCE(SUM(ven_total),0) total,COALESCE(SUM(ven_pagado),0) pagado,COALESCE(SUM(GREATEST(0,ven_total-ven_pagado)),0) saldo FROM venta WHERE loc_id=? AND ven_estado=1 AND ven_fecha>=? AND ven_fecha<?',[$loc,$inicio,$finExclusivo])->fetch(PDO::FETCH_ASSOC);
        $items=$this->q('SELECT COALESCE(SUM(d.vdp_cantidad),0) cantidad FROM venta_detalle_producto d JOIN venta v ON v.ven_id=d.ven_id WHERE v.loc_id=? AND v.ven_estado=1 AND v.ven_fecha>=? AND v.ven_fecha<?',[$loc,$inicio,$finExclusivo])->fetchColumn();
        $porEmitir=$this->q('SELECT COUNT(*) FROM venta WHERE loc_id=? AND ven_estado=1 AND tde_id IS NOT NULL AND fac_id IS NULL AND ven_pagado>=ven_total AND ven_fecha>=? AND ven_fecha<?',[$loc,$inicio,$finExclusivo])->fetchColumn();
        $utilidad=(new reporte_utilidad($this->db))->obtener($loc,$inicio,$fin);
        $stock=$this->q('SELECT COUNT(*) variantes,COALESCE(SUM(CASE WHEN COALESCE(s.cantidad,0)<=0 THEN 1 ELSE 0 END),0) sin_stock FROM producto_variante pv JOIN producto p ON p.pro_id=pv.pro_id LEFT JOIN stock_variante s ON s.pva_id=pv.pva_id AND s.loc_id=? WHERE pv.pva_estado=1 AND p.pro_estado=1',[$loc])->fetch(PDO::FETCH_ASSOC);
        $criticos=$this->q('SELECT p.pro_nombre,pv.pva_sku,COALESCE(s.cantidad,0) cantidad,u.und_abrev FROM producto_variante pv JOIN producto p ON p.pro_id=pv.pro_id JOIN unidad_medida u ON u.und_id=p.und_med LEFT JOIN stock_variante s ON s.pva_id=pv.pva_id AND s.loc_id=? WHERE pv.pva_estado=1 AND p.pro_estado=1 ORDER BY COALESCE(s.cantidad,0),p.pro_nombre,pv.pva_sku LIMIT 8',[$loc])->fetchAll(PDO::FETCH_ASSOC);
        $recientes=$this->q('SELECT v.ven_id,v.ven_fecha,v.ven_total,v.ven_pagado,GREATEST(0,v.ven_total-v.ven_pagado) saldo,COALESCE(e.ent_nombres,\'Cliente general\') cliente FROM venta v LEFT JOIN entidad e ON e.ent_id=v.ent_id WHERE v.loc_id=? AND v.ven_estado=1 AND v.ven_fecha>=? AND v.ven_fecha<? ORDER BY v.ven_fecha DESC,v.ven_id DESC LIMIT 8',[$loc,$inicio,$finExclusivo])->fetchAll(PDO::FETCH_ASSOC);
        $serieVentas=$this->q('SELECT DATE(ven_fecha) dia,SUM(ven_total) total FROM venta WHERE loc_id=? AND ven_estado=1 AND ven_fecha>=? AND ven_fecha<? GROUP BY DATE(ven_fecha) ORDER BY dia',[$loc,$inicio,$finExclusivo])->fetchAll(PDO::FETCH_ASSOC);
        $egresoReporte=(new reporte_movimientos($this->db))->obtener($loc,$inicio,$fin,'EGRESO');
        $ingresos=$this->q("SELECT COUNT(*) operaciones,COALESCE(SUM(mov_total),0) total FROM movimiento WHERE loc_id=? AND mov_tipo='INGRESO' AND mov_estado=1 AND mov_fecha>=? AND mov_fecha<?",[$loc,$inicio,$finExclusivo])->fetch(PDO::FETCH_ASSOC);
        $cobrosLocal=(float)$this->q('SELECT COALESCE(SUM(p.monto),0) FROM venta_pago p JOIN venta v ON v.ven_id=p.ven_id WHERE v.loc_id=? AND v.ven_estado=1 AND p.fecha>=? AND p.fecha<?',[$loc,$inicio,$finExclusivo])->fetchColumn();
        $pagosIngreso=(float)$this->q("SELECT COALESCE(SUM(p.mpa_monto),0) FROM movimiento_pago p JOIN movimiento m ON m.mov_id=p.mov_id WHERE m.loc_id=? AND m.mov_tipo='INGRESO' AND m.mov_estado=1 AND p.mpa_estado=1 AND p.mpa_fecha>=? AND p.mpa_fecha<?",[$loc,$inicio,$finExclusivo])->fetchColumn();
        $pagosEgreso=(float)$this->q("SELECT COALESCE(SUM(p.mpa_monto),0) FROM movimiento_pago p JOIN movimiento m ON m.mov_id=p.mov_id WHERE m.loc_id=? AND m.mov_tipo='EGRESO' AND m.mov_estado=1 AND p.mpa_estado=1 AND p.mpa_fecha>=? AND p.mpa_fecha<?",[$loc,$inicio,$finExclusivo])->fetchColumn();
        $movimientosRecientes=$this->q("SELECT m.mov_id,m.mov_tipo,m.mov_fecha,m.mov_total,COALESCE(p.pagado,0) aplicado,GREATEST(m.mov_total-COALESCE(p.pagado,0),0) saldo,COALESCE(e.ent_nombres,d.tipos,'Sin detalle') detalle FROM movimiento m LEFT JOIN entidad e ON e.ent_id=m.ent_id LEFT JOIN (SELECT mov_id,SUM(mpa_monto) pagado FROM movimiento_pago WHERE mpa_estado=1 GROUP BY mov_id) p ON p.mov_id=m.mov_id LEFT JOIN (SELECT md.mov_id,GROUP_CONCAT(DISTINCT t.tmc_nombre ORDER BY t.tmc_nombre SEPARATOR ', ') tipos FROM movimiento_detalle md JOIN tipo_movimiento t ON t.tmc_id=md.tmc_id GROUP BY md.mov_id) d ON d.mov_id=m.mov_id WHERE m.loc_id=? AND m.mov_estado=1 AND m.mov_fecha>=? AND m.mov_fecha<? ORDER BY m.mov_fecha DESC,m.mov_id DESC LIMIT 8",[$loc,$inicio,$finExclusivo])->fetchAll(PDO::FETCH_ASSOC);
        $mapVenta=[];foreach($serieVentas as $f)$mapVenta[$f['dia']]=(float)$f['total'];$mapUtilidad=[];foreach($utilidad['diario'] as $f)$mapUtilidad[$f['fecha']]=(float)$f['utilidad'];$dias=[];for($d=$desde;$d<=$hasta;$d=$d->modify('+1 day')){$key=$d->format('Y-m-d');$dias[]=['fecha'=>$key,'venta'=>$mapVenta[$key]??0,'utilidad'=>$mapUtilidad[$key]??0];}
        return ['estado'=>'ok','ventas'=>['operaciones'=>(int)$ventas['operaciones'],'total'=>(float)$ventas['total'],'pagado'=>(float)$ventas['pagado'],'saldo'=>(float)$ventas['saldo'],'unidades'=>(float)$items,'comprobantes_pendientes'=>(int)$porEmitir],'movimientos'=>['egresos'=>['operaciones'=>$egresoReporte['kpis']['egresos_n'],'total'=>$egresoReporte['kpis']['egresos'],'saldo'=>$egresoReporte['kpis']['saldo']],'ingresos'=>['operaciones'=>(int)$ingresos['operaciones'],'total'=>(float)$ingresos['total']]],'movimientos_recientes'=>$movimientosRecientes,'flujo'=>['cobros_ventas'=>$cobrosLocal,'ingresos'=>$pagosIngreso,'egresos'=>$pagosEgreso,'balance'=>$cobrosLocal+$pagosIngreso-$pagosEgreso],'utilidad'=>$utilidad['kpis'],'stock'=>['variantes'=>(int)$stock['variantes'],'sin_stock'=>(int)$stock['sin_stock'],'criticos'=>$criticos],'dias'=>$dias,'top'=>$utilidad['top'],'recientes'=>$recientes];
    }
}
